<?php
namespace Xdecaro\Component\Decarocourses\Administrator\Service;
defined('_JEXEC') or die;
use Joomla\CMS\Component\ComponentHelper; use Joomla\CMS\Factory; use Joomla\Database\DatabaseInterface;
final class EditionReminderService { private DatabaseInterface $db; private CrossProductIntegrationService $integrations; public function __construct(DatabaseInterface $db,CrossProductIntegrationService $i){$this->db=$db;$this->integrations=$i;} public function process(?int $days=null,int $limit=200):array{$p=ComponentHelper::getParams('com_decarocourses');$manager=max(0,(int)$p->get('integration_manager_user_id',0));$days=max(1,min(90,$days??(int)$p->get('integration_reminder_days',14)));$limit=max(1,min(500,$limit));$stats=['items'=>0,'notifications'=>0,'tasks'=>0,'skipped'=>0];if($manager<1)return $stats;[$today,$until]=$this->window($days);foreach($this->rows($today,$until,$limit) as $row){foreach(['registration_end'=>'registration_close','start_date'=>'edition_start'] as $field=>$kind){$date=(string)($row[$field]??'');if($date===''||$date<$today||$date>$until)continue;++$stats['items'];$title=$kind==='registration_close'?'Course registration closing: ':'Course edition starting: ';$title.=(string)$row['title'];$message=$title.' ('.$date.').';$base='courses:'.$kind.':'.(int)$row['id'].':'.$date;$n=$this->integrations->notify(['recipient_type'=>'user','recipient_id'=>(string)$manager,'category'=>'courses','priority'=>$date===$today?'high':'normal','title'=>$title,'message'=>$message,'source_entity'=>'edition','source_id'=>(string)$row['id'],'external_key'=>$base.':notification','payload'=>['edition_id'=>(int)$row['id'],'kind'=>$kind,'date'=>$date]]);if($n!==null)++$stats['notifications'];$t=$this->integrations->task(['title'=>$title,'description'=>$message,'priority'=>$date===$today?'high':'normal','due_at'=>$date.' 09:00:00','source_entity'=>'edition','source_id'=>(string)$row['id'],'external_key'=>$base.':task'],['type'=>'user','id'=>(string)$manager]);if($t!==null)++$stats['tasks'];if($n===null&&$t===null)++$stats['skipped'];}}return $stats;} private function rows(string $today,string $until,int $limit):array{$q=$this->db->getQuery(true)->select(['id','title','registration_end','start_date'])->from($this->db->quoteName('#__decarocourses_editions'))->where($this->db->quoteName('state').' = 1')->where('(('.$this->db->quoteName('registration_end').' BETWEEN :today AND :until) OR ('.$this->db->quoteName('start_date').' BETWEEN :today2 AND :until2))')->order($this->db->quoteName('start_date').' ASC')->bind(':today',$today)->bind(':until',$until)->bind(':today2',$today)->bind(':until2',$until);return array_values((array)$this->db->setQuery($q,0,$limit)->loadAssocList());} private function window(int $days):array{return [Factory::getDate('now','UTC')->format('Y-m-d'),Factory::getDate('+'.$days.' days','UTC')->format('Y-m-d')];} }
